class _Timer_extra_ghost_657451:
    """Simple timer/stopwatch."""
    def __init__(self):
        self._start = None
        self._elapsed = 0
    def start(self):
        self._start = __import__("time").time()
    def stop(self):
        if self._start:
            self._elapsed += __import__("time").time() - self._start
            self._start = None
    def reset(self):
        self._start = None
        self._elapsed = 0
    @property
    def elapsed(self):
        if self._start:
            return self._elapsed + (__import__("time").time() - self._start)
        return self._elapsed



class _Limiter_core_extra_657452:
    """Rate limiter."""
    def __init__(self, max_calls=10, period=1.0):
        self._calls = []
        self._max = max_calls
        self._period = period
    def acquire(self):
        now = __import__("time").time()
        self._calls = [t for t in self._calls if now - t < self._period]
        if len(self._calls) >= self._max:
            return False
        self._calls.append(now)
        return True



